#!/usr/bin/env node

/**
 * Reorganize items_game.txt into:
 *  - default.txt (KV)
 *  - bundle.txt  (KV)
 */

const fs = require("fs");
const vdf = require("vdf");
const path = require("path");

/* ------------------------------------------------------------ */
/* Args & IO                                                    */
/* ------------------------------------------------------------ */
const file = process.argv[2];
if (!file || !fs.existsSync(file)) {
    console.error("Usage: node reorganize_items_game.js <items_game.txt>");
    process.exit(1);
}

const dir = path.dirname(file);
const outDefault = path.join(dir, "default.txt");
const outBundle = path.join(dir, "bundle.txt");

/* ------------------------------------------------------------ */
/* Parse KV                                                     */
/* ------------------------------------------------------------ */
const text = fs.readFileSync(file, "utf8");
const kv = vdf.parse(text);

const root = kv.items_game;
if (!root || typeof root !== "object") {
    console.error("Invalid items_game.txt: missing items_game root");
    process.exit(1);
}

const items = root.items;
if (!items || typeof items !== "object") {
    console.error("Invalid items_game.txt: missing items block");
    process.exit(1);
}

/* ------------------------------------------------------------ */
/* Helpers                                                      */
/* ------------------------------------------------------------ */
function heroesFromUsedByHeroes(used) {
    if (!used || typeof used !== "object") return [];
    return Object.keys(used);
}

/* ------------------------------------------------------------ */
/* Build name -> itemdef map                                    */
/* ------------------------------------------------------------ */
const nameToDef = {};
for (const [id, v] of Object.entries(items)) {
    if (v && v.name) {
        nameToDef[v.name] = id;
    }
}

/* ------------------------------------------------------------ */
/* Collect defaults                                             */
/* ------------------------------------------------------------ */
const defaults = {}; // hero -> [{id, slot}]

for (const [id, v] of Object.entries(items)) {
    if (!v || v.prefab !== "default_item") continue;

    const heroes = heroesFromUsedByHeroes(v.used_by_heroes);
    if (heroes.length === 0) continue;

    for (const hero of heroes) {
        defaults[hero] ??= [];
        defaults[hero].push({
            id,
            slot: v.item_slot || ""
        });
    }
}

/* ------------------------------------------------------------ */
/* Collect bundles                                              */
/* ------------------------------------------------------------ */
const bundles = {}; // hero -> bundleKey -> [{id, slot}]

for (const [id, v] of Object.entries(items)) {
    if (!v || v.prefab !== "bundle") continue;
    if (!v.bundle || typeof v.bundle !== "object") continue;
    if (!v.name) continue;

    const bundleKey = `${v.name}__${id}`;
    const wearableList = [];
    const derivedHeroes = new Set();

    // bundle members
    for (const memberName of Object.keys(v.bundle)) {
        const wid = nameToDef[memberName];
        if (!wid || wid.prefab == "loading_screen") continue;

        const w = items[wid];
        wearableList.push({
            id: wid,
            slot: w?.item_slot || ""
        });

        if (w?.used_by_heroes && typeof w.used_by_heroes === "object") {
            for (const h of Object.keys(w.used_by_heroes)) {
                derivedHeroes.add(h);
            }
        }
    }

    // hero resolution
    let heroes = [];
    if (v.used_by_heroes && typeof v.used_by_heroes === "object") {
        heroes = Object.keys(v.used_by_heroes);
    } else if (derivedHeroes.size > 0) {
        heroes = Array.from(derivedHeroes);
    }

    if (heroes.length === 0) {
        heroes = ["__UNRESOLVED__"];
    }

    for (const hero of heroes) {
        bundles[hero] ??= {};
        bundles[hero][bundleKey] = wearableList.slice();
    }
}

/* ------------------------------------------------------------ */
/* Write default.txt                                            */
/* ------------------------------------------------------------ */
let out = "";
for (const hero of Object.keys(defaults).sort()) {
    out += `"${hero}"\n{\n`;
    for (const it of defaults[hero]) {
        out += `    "${it.id}" "${it.slot}"\n`;
    }
    out += "}\n\n";
}
fs.writeFileSync(outDefault, out);

/* ------------------------------------------------------------ */
/* Write bundle.txt                                             */
/* ------------------------------------------------------------ */
out = "";
for (const hero of Object.keys(bundles).sort()) {
    out += `"${hero}"\n{\n`;
    const bundleMap = bundles[hero];

    for (const bkey of Object.keys(bundleMap).sort()) {
        const list = bundleMap[bkey];
        out += `    "${bkey}"\n    {\n`;
        for (const it of list) {
            out += `        "${it.id}" "${it.slot}"\n`;
        }
        out += "    }\n";
    }
    out += "}\n\n";
}
fs.writeFileSync(outBundle, out);

